export function getLanguage() {
  try {
    return localStorage.getItem(preferenceKey) === 'en' ? 'en' : 'vi'
  } catch {
    return 'vi'
  }
}

export function translateText(value) {
  if (typeof value !== 'string' || getLanguage() !== 'en') return value
  const text = value.replace(/\s+/g, ' ')
  const trimmed = text.trim()
  const translated = ENGLISH[trimmed]
  const packageCount = trimmed.match(/^(\d+) gói dịch vụ$/)
  const monthCount = trimmed.match(/^(\d+) tháng$/)
  const selectionCount = trimmed.match(/^Đã chọn (\d+) môn · yêu cầu (\d+)$/)
  const dynamicTranslation = packageCount ? `${packageCount[1]} service packages`
    : monthCount ? `${monthCount[1]} months`
        : selectionCount ? `${selectionCount[1]} selected · ${selectionCount[2]} required`
        : null
  if (!translated && !dynamicTranslation) {
    const segments = trimmed.split(/(\s+[·|/]\s+)/)
    if (segments.length > 1) {
      const localized = segments.map((segment) => /^\s+[·|/]\s+$/.test(segment) ? segment : translateText(segment)).join('')
      if (localized !== trimmed) {
        const leading = value.match(/^\s*/)?.[0] || ''
        const trailing = value.match(/\s*$/)?.[0] || ''
        return `${leading}${localized}${trailing}`
      }
    }
    const colonIndex = trimmed.indexOf(':')
    if (colonIndex > 0) {
      const prefix = trimmed.slice(0, colonIndex + 1)
      const translatedPrefix = ENGLISH[prefix]
      if (translatedPrefix) {
        const leading = value.match(/^\s*/)?.[0] || ''
        const trailing = value.match(/\s*$/)?.[0] || ''
        return `${leading}${translatedPrefix}${trimmed.slice(colonIndex + 1)}${trailing}`
      }
    }
    return value
  }
  const leading = value.match(/^\s*/)?.[0] || ''
  const trailing = value.match(/\s*$/)?.[0] || ''
  return `${leading}${translated || dynamicTranslation}${trailing}`
}

const ENGLISH_SOURCE = Object.entries(ENGLISH).reduce((sources, [source, translated]) => {
  if (!sources.has(translated)) sources.set(translated, source)
  return sources
}, new Map())

export function getEnglishSource(value) {
  if (typeof value !== 'string') return value
  const trimmed = value.replace(/\s+/g, ' ').trim()
  const source = ENGLISH_SOURCE.get(trimmed)
  if (source) return source
  const months = trimmed.match(/^(\d+) months?$/)
  if (months) return `${months[1]} tháng`
  const packages = trimmed.match(/^(\d+) service packages?$/)
  if (packages) return `${packages[1]} gói dịch vụ`
  const selection = trimmed.match(/^(\d+) selected · (\d+) required$/)
  if (selection) return `Đã chọn ${selection[1]} môn · yêu cầu ${selection[2]}`
  return value
}

export function subscribeLanguage(callback) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener('unisports:language-changed', callback)
  window.addEventListener('storage', callback)
  return () => {
    window.removeEventListener('unisports:language-changed', callback)
    window.removeEventListener('storage', callback)
  }
}

export function useLanguage() {
  const [language, setLanguage] = useState(getLanguage)
  useEffect(() => subscribeLanguage((event) => {
    setLanguage(event?.detail || getLanguage())
  }), [])
  return language
}

export function saveLanguage(language) {
  const nextLanguage = language === 'en' ? 'en' : 'vi'
  try {
    localStorage.setItem(preferenceKey, nextLanguage)
  } catch {
    // Keep the in-page control usable if browser storage is unavailable.
  }
  if (typeof document !== 'undefined') document.documentElement.lang = nextLanguage
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('unisports:language-changed', { detail: nextLanguage }))
  }
}
